// Build a short summary of yesterday's calls.
const calls = $input.all().map((item) => item.json).filter((call) => call.id);
const day = $today.minus({ days: 1 }).toFormat('yyyy-MM-dd');

const byResult = {};
let seconds = 0;
for (const call of calls) {
  const result = call.call_result || call.call_status || 'unknown';
  byResult[result] = (byResult[result] || 0) + 1;
  seconds += Number(call.duration) || 0;
}

const lines = [
  `*ContactShip calls on ${day}*`,
  `${calls.length} calls, ${Math.round(seconds / 60)} minutes in total`,
  ...Object.entries(byResult)
    .sort((a, b) => b[1] - a[1])
    .map(([result, count]) => `• ${result.replace(/_/g, ' ')}: ${count}`),
];

const highlights = calls
  .filter((call) => call.call_result === 'answered' && call.summary)
  .slice(0, 5)
  .map((call) => `• ${call.contact_name || call.contact_phone || 'Unknown contact'}: ${call.summary}`);
if (highlights.length) lines.push('', '*Answered calls*', ...highlights);
if (!calls.length) lines.push('No calls yesterday.');

return [{ json: { text: lines.join('\n') } }];
